//! Build script: generates the Tauri context and the ACL permissions for our app commands.

/// Every `#[tauri::command]` registered in `src/lib.rs`. Each gets an autogenerated
/// `allow-<name>` permission which `capabilities/default.json` grants to the main window.
const COMMANDS: &[&str] = &[
    "get_shell_state",
    "detect_hardware",
    "disk_space",
    "set_library_path",
    "set_language",
    "bootstrap_start",
    "bootstrap_cancel",
    "bootstrap_repair",
    "finish_onboarding",
    "backend_start",
    "backend_restart",
    "backend_stop",
    "backend_logs",
    "set_close_to_tray",
    "set_tray_status",
    "reveal_path",
    "open_logs_folder",
    "quit_app",
    "frontend_pong",
    "check_python",
    "set_runtime_python",
    "install_runtime_requirements",
    "find_pythons",
    "accept_terms",
];

fn main() {
    // `bundle.resources` points at `resources/`, which is filled by
    // `stellaria/scripts/stage-bundle.mjs` and is not committed. An empty directory is
    // fine for dev builds and `cargo check`; a missing one makes tauri-build fail.
    if let Err(err) = std::fs::create_dir_all("resources") {
        println!("cargo:warning=could not create resources/: {err}");
    }

    tauri_build::try_build(
        tauri_build::Attributes::new()
            .app_manifest(tauri_build::AppManifest::new().commands(COMMANDS)),
    )
    .expect("failed to run tauri-build");
}
